import React, { useEffect, useMemo, useState } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import { getProductCategories, getProducts } from '../services/api';
import ProductCard from '../components/ProductCard';
import { useTheme } from '../context/ThemeContext';
import Toast from '../components/Toast';
import useToast from '../hooks/useToast';

const Products = () => {
  const { id } = useParams();
  const [searchParams, setSearchParams] = useSearchParams();
  const { isDarkMode } = useTheme();
  const { toasts, removeToast } = useToast();

  const [categories, setCategories] = useState([]);
  const [products, setProducts] = useState([]);
  const [pagination, setPagination] = useState({ page: 1, pages: 1, total: 0 });
  const [loading, setLoading] = useState(true);
  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);

  const category = searchParams.get('category') || '';
  const search = searchParams.get('search') || '';
  const page = Number(searchParams.get('page')) || 1;
  const sort = searchParams.get('sort') || 'newest';
  const minPrice = searchParams.get('minPrice') || '';
  const maxPrice = searchParams.get('maxPrice') || '';
  const minRating = searchParams.get('minRating') || '';
  const limit = Number(searchParams.get('limit')) || 24;

  const [searchDraft, setSearchDraft] = useState(search);

  useEffect(() => {
    setSearchDraft(search);
  }, [search]);
  const categoryMeta = useMemo(
    () => [
      { key: '', label: 'All', emoji: "\uD83D\uDECD\uFE0F" },
      { key: 'groceries', label: 'Groceries', emoji: "\uD83D\uDED2" },
      { key: 'fashion', label: 'Fashion', emoji: "\uD83D\uDC55" },
      { key: 'electronics', label: 'Electronics', emoji: "\uD83D\uDCF1" },
      { key: 'home', label: 'Home', emoji: "\uD83C\uDFE0" },
      { key: 'beauty', label: 'Beauty', emoji: "\uD83E\uDDF4" },
      { key: 'accessories', label: 'Accessories', emoji: "\uD83D\uDC5C" },
      { key: 'sweets', label: 'Sweets', emoji: "\uD83C\uDF6C" },
      { key: 'cake', label: 'Cake', emoji: "\uD83C\uDF70" },
      { key: 'milk', label: 'Milk', emoji: "\uD83E\uDD5B" },
      { key: 'ghee', label: 'Ghee', emoji: "\uD83E\uDDC8" },
      { key: 'cheese', label: 'Cheese', emoji: "\uD83E\uDDC0" },
      { key: 'butter', label: 'Butter', emoji: "\uD83E\uDDC8" },
      { key: 'curd', label: 'Curd', emoji: "\uD83E\uDD63" },
      { key: 'paneer', label: 'Paneer', emoji: "\uD83E\uDDC0" },
      { key: 'cream', label: 'Cream', emoji: "\uD83C\uDF66" },
      { key: 'yogurt', label: 'Yogurt', emoji: "\uD83E\uDD5B" },
      { key: 'lassi', label: 'Lassi', emoji: "\uD83E\uDD64" },
      { key: 'buttermilk', label: 'Buttermilk', emoji: "\uD83E\uDD64" }
    ],
    []
  );
  const setParam = (key, value) => {
    const params = new URLSearchParams(searchParams);
    if (value === '' || value === null || value === undefined) params.delete(key);
    else params.set(key, String(value));
    params.delete('page');
    setSearchParams(params);
  };

  const clearFilters = () => {
    const params = new URLSearchParams(searchParams);
    ['minPrice', 'maxPrice', 'minRating', 'sort', 'limit'].forEach((k) => params.delete(k));
    params.delete('page');
    setSearchParams(params);
  };

  const setCategory = (cat) => setParam('category', cat || '');

  const applySearch = () => setParam('search', searchDraft.trim());

  const fetchCategories = async () => {
    try {
      const res = await getProductCategories();
      setCategories(Array.isArray(res.data) ? res.data : []);
    } catch (error) {
      console.error('Error fetching categories:', error);
      setCategories([]);
    }
  };

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const res = await getProducts({
        category,
        search,
        page,
        sort,
        minPrice: minPrice || undefined,
        maxPrice: maxPrice || undefined,
        minRating: minRating || undefined,
        limit
      });

      setProducts(res.data?.products || []);
      setPagination({
        page: res.data?.page || 1,
        pages: res.data?.pages || 1,
        total: res.data?.total || 0
      });
    } catch (error) {
      console.error('Error fetching products:', error);
      setProducts([]);
      setPagination({ page: 1, pages: 1, total: 0 });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    if (id) return;
    fetchProducts();
  }, [id, category, search, page, sort, minPrice, maxPrice, minRating, limit]);

  const activeCategoryLabel = useMemo(() => {
    const m = categoryMeta.find((c) => c.key === category);
    if (m) return `${m.emoji} ${m.label}`;
    if (category) return category;
    return '\uD83D\uDECD\uFE0F All Products';
  }, [category, categoryMeta]);

  const sortTabs = useMemo(
    () => [
      { key: 'newest', label: 'Newest First' },
      { key: 'rating_desc', label: 'Popularity' },
      { key: 'price_asc', label: 'Price -- Low to High' },
      { key: 'price_desc', label: 'Price -- High to Low' }
    ],
    []
  );

  const showingText = useMemo(() => {
    const total = Number(pagination.total || 0);
    const start = total === 0 ? 0 : (page - 1) * limit + 1;
    const end = total === 0 ? 0 : Math.min(total, (page - 1) * limit + products.length);
    const q = search ? ` for "${search}"` : '';
    return `Showing ${start} â€“ ${end} of ${total} results${q}`;
  }, [pagination.total, page, limit, products.length, search]);

  const renderSidebar = ({ compact = false } = {}) => (
    <div className="space-y-4">
      {/* Categories */}
      <div
        className={`rounded-2xl p-4 ${
          isDarkMode ? 'bg-gray-900/60 border border-white/10' : 'bg-white border border-gray-200'
        }`}
      >
        <div className={`text-sm font-bold tracking-wide mb-3 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>CATEGORIES</div>
        <div className={`${compact ? 'max-h-[40vh]' : 'max-h-[55vh]'} overflow-auto pr-1 space-y-2`}>
          {([
            ...categoryMeta,
            ...categories.map((c) => ({
              key: c,
              label: c,
              emoji: categoryMeta.find((m) => m.key === c)?.emoji || '\uD83D\uDECD\uFE0F'
            }))
          ] || [])
            .filter((x, idx, arr) => idx === arr.findIndex((y) => y.key === x.key))
            .map((c) => (
              <button
                key={c.key || 'all'}
                type="button"
                onClick={() => setCategory(c.key)}
                className={`w-full text-left px-3 py-2 rounded-xl font-medium transition text-sm ${
                  (c.key || '') === category
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-sm'
                    : isDarkMode
                      ? 'text-gray-200 hover:bg-white/5'
                      : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                <span className="mr-2">{c.emoji}</span>
                <span className="capitalize">{c.label}</span>
              </button>
            ))}
        </div>
      </div>

      {/* Filters */}
      <div
        className={`rounded-2xl p-4 ${
          isDarkMode ? 'bg-gray-900/60 border border-white/10' : 'bg-white border border-gray-200'
        }`}
      >
        <div className="flex items-center justify-between mb-3">
          <div className={`text-sm font-bold tracking-wide ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>FILTERS</div>
          <button
            type="button"
            onClick={clearFilters}
            className={`text-xs font-semibold px-3 py-1.5 rounded-xl border transition ${
              isDarkMode ? 'border-white/10 text-gray-200 hover:bg-white/5' : 'border-gray-200 text-gray-700 hover:bg-gray-100'
            }`}
          >
            Reset
          </button>
        </div>

        <div className="space-y-3">
          <div>
            <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Sort</label>
            <select
              value={sort}
              onChange={(e) => setParam('sort', e.target.value)}
              className={`w-full px-3 py-2.5 rounded-xl border ${
                isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-900'
              } focus:outline-none focus:ring-2 focus:ring-primary-500`}
            >
              <option value="newest">Newest</option>
              <option value="price_asc">Price: Low â†’ High</option>
              <option value="price_desc">Price: High â†’ Low</option>
              <option value="rating_desc">Top Rated</option>
            </select>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Min â‚¹</label>
              <input
                type="number"
                inputMode="numeric"
                value={minPrice}
                onChange={(e) => setParam('minPrice', e.target.value)}
                className={`w-full px-3 py-2.5 rounded-xl border ${
                  isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-900'
                } focus:outline-none focus:ring-2 focus:ring-primary-500`}
                placeholder="0"
                min="0"
              />
            </div>
            <div>
              <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Max â‚¹</label>
              <input
                type="number"
                inputMode="numeric"
                value={maxPrice}
                onChange={(e) => setParam('maxPrice', e.target.value)}
                className={`w-full px-3 py-2.5 rounded-xl border ${
                  isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-900'
                } focus:outline-none focus:ring-2 focus:ring-primary-500`}
                placeholder="9999"
                min="0"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Min Rating</label>
              <select
                value={minRating}
                onChange={(e) => setParam('minRating', e.target.value)}
                className={`w-full px-3 py-2.5 rounded-xl border ${
                  isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-900'
                } focus:outline-none focus:ring-2 focus:ring-primary-500`}
              >
                <option value="">Any</option>
                <option value="4">4â˜… & up</option>
                <option value="3">3â˜… & up</option>
                <option value="2">2â˜… & up</option>
                <option value="1">1â˜… & up</option>
              </select>
            </div>
            <div>
              <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>Per Page</label>
              <select
                value={limit}
                onChange={(e) => setParam('limit', e.target.value)}
                className={`w-full px-3 py-2.5 rounded-xl border ${
                  isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-200 text-gray-900'
                } focus:outline-none focus:ring-2 focus:ring-primary-500`}
              >
                <option value="12">12</option>
                <option value="24">24</option>
                <option value="36">36</option>
                <option value="48">48</option>
              </select>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-black dark:to-black">
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Top bar */}
        <div
          className={`sticky top-0 z-30 -mx-4 px-4 py-3 mb-6 ${
            isDarkMode ? 'bg-black/50' : 'bg-white/60'
          } backdrop-blur-xl border-b ${isDarkMode ? 'border-white/10' : 'border-gray-200'}`}
        >
          <div className="max-w-7xl mx-auto flex flex-col gap-3">
            <div className="flex items-center justify-between gap-3">
              <div>
                <div className={`text-xl md:text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Products</div>
                <div className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>{activeCategoryLabel}</div>
              </div>
              <button
                type="button"
                onClick={() => setMobileFiltersOpen(true)}
                className={`lg:hidden px-4 py-2 rounded-xl font-semibold border ${
                  isDarkMode ? 'border-white/10 text-gray-100 hover:bg-white/5' : 'border-gray-200 text-gray-800 hover:bg-gray-100'
                }`}
              >
                Filters
              </button>
            </div>

            <div className="flex flex-col md:flex-row gap-3">
              <div className="relative flex-1">
                <input
                  value={searchDraft}
                  onChange={(e) => setSearchDraft(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') applySearch();
                  }}
                  placeholder="Search productsâ€¦"
                  className={`w-full px-4 py-3 pl-11 rounded-2xl border ${
                    isDarkMode ? 'bg-gray-800/40 border-white/10 text-white placeholder-gray-400' : 'bg-white border-gray-200 text-gray-900 placeholder-gray-500'
                  } focus:outline-none focus:ring-2 focus:ring-primary-500`}
                />
                <svg className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <button
                type="button"
                onClick={applySearch}
                className="px-5 py-3 rounded-2xl font-semibold bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-sm hover:shadow-md"
              >
                Search
              </button>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Desktop sidebar */}
          <aside className="hidden lg:block lg:col-span-3 lg:sticky lg:top-24 lg:self-start">
            {renderSidebar()}
          </aside>

          {/* Main */}
          <main className="lg:col-span-9">
            {/* Breadcrumb + results */}
            <div className={`rounded-2xl ${isDarkMode ? 'bg-gray-900/60 border border-white/10' : 'bg-white border border-gray-200'} mb-4`}>
              <div className="px-4 pt-4">
                <div className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                  Home <span className="mx-1">â€º</span> Products {category ? <><span className="mx-1">â€º</span> <span className="capitalize">{category}</span></> : null}
                </div>
                <div className={`mt-2 font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
                  {loading ? 'Loadingâ€¦' : showingText}
                </div>
              </div>

              {/* Sort tabs */}
              <div className={`mt-3 px-4 py-3 border-t ${isDarkMode ? 'border-white/10' : 'border-gray-200'}`}>
                <div className="flex flex-wrap items-center gap-2">
                  <div className={`text-sm font-semibold mr-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>Sort By</div>
                  {sortTabs.map((t) => (
                    <button
                      key={t.key}
                      type="button"
                      onClick={() => setParam('sort', t.key)}
                      className={`px-2.5 py-1.5 rounded-lg text-sm font-medium border transition ${
                        sort === t.key
                          ? 'border-primary-500 text-primary-600 dark:text-primary-300 bg-primary-500/10'
                          : isDarkMode
                            ? 'border-white/10 text-gray-200 hover:bg-white/5'
                            : 'border-gray-200 text-gray-800 hover:bg-gray-50'
                      }`}
                    >
                      {t.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {id ? (
              <div className={`rounded-2xl p-6 ${isDarkMode ? 'bg-gray-800/40 border border-white/10' : 'bg-white/80 border border-gray-200'}`}>
                <div className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Product view</div>
                <div className={`text-sm mt-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                  This route expects a dedicated Product Detail page. Current id: <span className="font-mono">{id}</span>
                </div>
              </div>
            ) : loading ? (
              <div className={`rounded-2xl ${isDarkMode ? 'bg-gray-900/60 border border-white/10' : 'bg-white border border-gray-200'}`}>
                {Array.from({ length: 8 }).map((_, idx) => (
                  <div
                    key={idx}
                    className={`h-28 border-b last:border-b-0 ${isDarkMode ? 'border-white/10' : 'border-gray-200'} animate-pulse`}
                  />
                ))}
              </div>
            ) : products.length > 0 ? (
              <>
                <div className={`rounded-2xl overflow-hidden ${isDarkMode ? 'bg-gray-900/60 border border-white/10' : 'bg-white border border-gray-200'}`}>
                  {products.map((p, idx) => (
                    <div key={p._id} className={`border-b last:border-b-0 ${isDarkMode ? 'border-white/10' : 'border-gray-200'}`}>
                      <ProductCard product={p} onCartUpdate={fetchProducts} index={idx} variant="list" />
                    </div>
                  ))}
                </div>

                {pagination.pages > 1 ? (
                  <div className="mt-6 flex items-center justify-center gap-2">
                    <button
                      type="button"
                      onClick={() => setParam('page', Math.max(1, pagination.page - 1))}
                      disabled={pagination.page <= 1}
                      className={`px-4 py-2 rounded-xl font-semibold border transition disabled:opacity-50 ${
                        isDarkMode ? 'border-white/10 text-gray-100 hover:bg-white/5' : 'border-gray-200 text-gray-800 hover:bg-gray-100'
                      }`}
                    >
                      Prev
                    </button>
                    <div className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Page {pagination.page} / {pagination.pages}
                    </div>
                    <button
                      type="button"
                      onClick={() => setParam('page', Math.min(pagination.pages, pagination.page + 1))}
                      disabled={pagination.page >= pagination.pages}
                      className={`px-4 py-2 rounded-xl font-semibold border transition disabled:opacity-50 ${
                        isDarkMode ? 'border-white/10 text-gray-100 hover:bg-white/5' : 'border-gray-200 text-gray-800 hover:bg-gray-100'
                      }`}
                    >
                      Next
                    </button>
                  </div>
                ) : null}
              </>
            ) : (
              <div
                className={`rounded-2xl p-10 text-center ${
                  isDarkMode ? 'bg-gray-800/40 border border-white/10' : 'bg-white/80 border border-gray-200'
                }`}
              >
                <div className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>No products found</div>
                <div className={`mt-2 text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                  Try clearing filters, changing category, or searching with a different keyword.
                </div>
                <button
                  type="button"
                  onClick={() => {
                    const params = new URLSearchParams();
                    setSearchParams(params);
                  }}
                  className="mt-6 px-6 py-3 rounded-2xl font-semibold bg-gradient-to-r from-primary-500 to-secondary-500 text-white"
                >
                  Reset all
                </button>
              </div>
            )}
          </main>
        </div>

        {/* Mobile filter drawer */}
        {mobileFiltersOpen ? (
          <div className="lg:hidden fixed inset-0 z-50">
            <div
              className="absolute inset-0 bg-black/60"
              onClick={() => setMobileFiltersOpen(false)}
              role="button"
              tabIndex={0}
            />
            <div
              className={`absolute right-0 top-0 h-full w-[92%] max-w-sm ${
                isDarkMode ? 'bg-black' : 'bg-white'
              } shadow-2xl border-l ${isDarkMode ? 'border-white/10' : 'border-gray-200'} p-4 overflow-auto`}
            >
              <div className="flex items-center justify-between mb-4">
                <div className={`text-lg font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>Filters</div>
                <button
                  type="button"
                  onClick={() => setMobileFiltersOpen(false)}
                  className={`px-3 py-2 rounded-xl border ${
                    isDarkMode ? 'border-white/10 text-gray-100 hover:bg-white/5' : 'border-gray-200 text-gray-800 hover:bg-gray-100'
                  }`}
                >
                  Close
                </button>
              </div>
              {renderSidebar({ compact: true })}
              <button
                type="button"
                onClick={() => setMobileFiltersOpen(false)}
                className="mt-4 w-full px-5 py-3 rounded-2xl font-semibold bg-gradient-to-r from-primary-500 to-secondary-500 text-white"
              >
                Apply
              </button>
            </div>
          </div>
        ) : null}
      </div>

      {toasts.map((toast) => (
        <Toast
          key={toast.id}
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          onClose={() => removeToast(toast.id)}
        />
      ))}
    </div>
  );
};

export default Products;
